def process(matchMsaNames) -> pd.DataFrame:
    import pandas as pd

    df = matchMsaNames.copy()

    # Filter to metros with estimated 2023 population > 1,000,000
    df = df[pd.to_numeric(df['pop2023_est'], errors='coerce') > 1_000_000]

    avg_reports = pd.to_numeric(df['reports'], errors='coerce').mean()

    return pd.DataFrame([{
        'avg_reports_over_1m_pop_2023': float(avg_reports),
        'n_metros': int(df.shape[0])
    }])
